RKfill("fe",[{},{"lang":"text","run":false,"b":["Setiap permintaan HTTP punya <b>metode</b> (GET untuk membaca, POST untuk mengirim, PUT/PATCH untuk mengubah, DELETE untuk menghapus), <b>header</b> (informasi tambahan), dan kadang <b>body</b>. Respons membawa kode status: 2xx berhasil, 3xx pengalihan, 4xx kesalahan dari sisi klien, 5xx kesalahan server.","<b>HTTPS</b> mengenkripsi lalu lintas dengan TLS, sehingga kata sandi dan data pembayaran tidak bisa dibaca di jaringan Wi-Fi publik. Browser modern menandai situs non-HTTPS sebagai tidak aman.","Header <code>Cache-Control</code> memberi tahu browser berapa lama file boleh disimpan. File dengan nama ber-hash (<code>app.3f9a1c.js</code>) aman di-cache setahun karena namanya berubah setiap isinya berubah; dokumen HTML biasanya <code>no-cache</code> agar selalu diperiksa ulang."],"code":"GET /assets/app.3f9a1c.js HTTP/2\nHost: tokonusantara.id\n\nHTTP/2 200\ncontent-type: text/javascript\ncache-control: public, max-age=31536000, immutable\n\nGET / HTTP/2\nHTTP/2 200\ncontent-type: text/html\ncache-control: no-cache","pts":["Metode: GET, POST, PUT/PATCH, DELETE.","Status: 2xx sukses, 3xx pengalihan, 4xx salah klien, 5xx salah server.","HTTPS = HTTP + enkripsi TLS.","Aset ber-hash di-cache lama; HTML diperiksa ulang."],"q":[["Kode 401 masuk kelompok?",["Kesalahan klien (belum login)","Sukses","Kesalahan server"],0,"4xx adalah kesalahan di sisi permintaan."],["Kenapa file app.3f9a1c.js boleh di-cache setahun?",["Namanya berubah setiap isinya berubah","Karena JS tidak pernah berubah","Karena HTTPS"],0,"Ini disebut cache busting."]]},{"viz":"render","b":["Setelah HTML diterima, browser membangun <b>DOM</b> dari HTML dan <b>CSSOM</b> dari CSS, menggabungkannya menjadi <b>render tree</b>, menghitung ukuran dan posisi setiap kotak (<b>layout</b>), mewarnainya (<b>paint</b>), lalu menyusun lapisan (<b>composite</b>).","CSS menghambat tampilan dan script biasa menghambat pembacaan HTML. Karena itu CSS penting dimuat lebih awal dan script diberi defer.","Saat JavaScript mengubah lebar atau posisi elemen, browser mengulang layout dan paint (mahal). Mengubah transform dan opacity cukup mengulang composite (murah), itulah alasan animasi sebaiknya memakai keduanya."],"pts":["HTML → DOM, CSS → CSSOM, lalu render tree.","Layout menghitung posisi, paint mewarnai, composite menyusun lapisan.","Ubah transform/opacity untuk animasi yang mulus."],"q":[["Mengubah width elemen memicu?",["Layout, paint, composite","Hanya composite","Tidak ada apa-apa"],0,"Ukuran berubah sehingga posisi harus dihitung ulang."]]},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{"console":true,"viz":"jsloop","b":["JavaScript di browser berjalan di <b>satu thread</b>. Agar halaman tidak membeku saat menunggu jaringan atau timer, pekerjaan yang menunggu diserahkan ke browser, lalu callback-nya diantrekan.","Ada dua antrean: <b>microtask</b> (Promise, await) dan <b>macrotask</b> (setTimeout, event klik). Setelah kode sinkron selesai, semua microtask dijalankan dulu, baru satu macrotask, dan seterusnya. Tebak urutan keluaran sebelum menjalankan."],"html":"<p>Lihat panel Konsol.</p>","js":"console.log(\"1. mulai\");\nsetTimeout(() => console.log(\"4. setTimeout (macrotask)\"), 0);\nPromise.resolve().then(() => console.log(\"3. promise (microtask)\"));\nconsole.log(\"2. selesai kode sinkron\");","pts":["Satu thread, tidak memblokir lewat antrean callback.","Urutan: sinkron, semua microtask, lalu macrotask.","setTimeout 0 tetap menunggu kode sinkron dan microtask."],"q":[["Mana yang jalan lebih dulu: Promise.then atau setTimeout 0?",["Promise.then","setTimeout 0","Acak"],0,"Microtask didahulukan."]],"pro":[{"t":"Jalankan permintaan bersamaan dengan Promise.all","tag":"Lebih cepat","why":"Tiga <code>await</code> berturut-turut menunggu satu per satu. Kalau permintaannya tidak saling bergantung, <code>Promise.all</code> menjalankannya bersamaan, sehingga waktu tunggunya hanya selama permintaan terlama.","lang":"js","a":"const tunda = (ms, v) => new Promise((r) => setTimeout(() => r(v), ms));\n(async () => {\n  const mulai = Date.now();\n  const produk = await tunda(300, \"produk\");\n  const ulasan = await tunda(300, \"ulasan\");\n  const stok = await tunda(300, \"stok\");\n  console.log(produk, ulasan, stok);\n  console.log(\"±\" + Math.round((Date.now() - mulai) / 100) * 100 + \" ms\");\n})();","b":"const tunda = (ms, v) => new Promise((r) => setTimeout(() => r(v), ms));\n(async () => {\n  const mulai = Date.now();\n  const [produk, ulasan, stok] = await Promise.all([\n    tunda(300, \"produk\"), tunda(300, \"ulasan\"), tunda(300, \"stok\"),\n  ]);\n  console.log(produk, ulasan, stok);\n  console.log(\"±\" + Math.round((Date.now() - mulai) / 100) * 100 + \" ms\");\n})();","outA":"produk ulasan stok\n±900 ms","outB":"produk ulasan stok\n±300 ms"}]},{"lang":"js","run":false,"b":["Kode besar dipecah menjadi <b>modul</b>: satu file satu tanggung jawab. <code>export</code> membagikan fungsi atau nilai, <code>import</code> memakainya. Ada named export (bisa banyak) dan default export (satu per file).","Di browser, pakai <code>&lt;script type=\"module\"&gt;</code>. Modul otomatis memakai mode ketat dan bersifat defer. <code>import()</code> dinamis memuat modul hanya saat dibutuhkan, cara dasar code splitting."],"code":"// format.js\nexport const rupiah = n => \"Rp\" + n.toLocaleString(\"id-ID\");\nexport default function judul(s) { return s[0].toUpperCase() + s.slice(1); }\n\n// main.js\nimport judul, { rupiah } from \"./format.js\";\nconsole.log(judul(\"kopi\"), rupiah(85000));   // Kopi Rp85.000\n\n// muat grafik hanya saat tombol diklik\ndocument.querySelector(\"#lihat\").onclick = async () => {\n  const { gambarGrafik } = await import(\"./grafik.js\");\n  gambarGrafik();\n};","pts":["export/import untuk membagi kode.","Named export banyak, default export satu.","type=\"module\" di browser.","import() dinamis untuk memuat saat perlu."],"q":[["Sintaks memakai named export rupiah?",["import { rupiah } from \"./format.js\"","import rupiah from \"./format.js\"","require rupiah"],0,"Named export memakai kurung kurawal."]]},{"b":["Browser menyediakan banyak <b>Web API</b>: <code>localStorage</code> menyimpan data kecil yang bertahan setelah browser ditutup, <code>IntersectionObserver</code> memberi tahu saat elemen masuk layar (untuk lazy load atau animasi muncul), <code>Clipboard</code>, <code>Geolocation</code>, <code>Notification</code>, dan lainnya.","Selalu periksa ketersediaan API dan bungkus akses storage dengan try/catch, karena bisa ditolak di mode privat."],"html":"<p>Kunjungan ke pratinjau ini: <b id=\"n\">?</b></p>\n<div style=\"height:220px;overflow:auto;border:1px solid #ddd\" id=\"area\">\n  <div style=\"height:300px\"></div>\n  <p id=\"target\" class=\"kotak\">Saya muncul saat terlihat</p>\n  <div style=\"height:60px\"></div>\n</div>","css":"body{font:14px system-ui,sans-serif}.kotak{opacity:0;transform:translateY(20px);transition:all .5s;background:#E9EFF5;padding:10px;border-radius:8px}.kotak.tampak{opacity:1;transform:none}","js":"try {\n  const n = Number(localStorage.getItem(\"kunjungan\") || 0) + 1;\n  localStorage.setItem(\"kunjungan\", n);\n  document.getElementById(\"n\").textContent = n;\n} catch (e) { document.getElementById(\"n\").textContent = \"storage tidak tersedia\"; }\n\nconst io = new IntersectionObserver(es => es.forEach(en => {\n  if (en.isIntersecting) en.target.classList.add(\"tampak\");\n}), { root: document.getElementById(\"area\") });\nio.observe(document.getElementById(\"target\"));","task":{"q":"Gulir kotak di pratinjau sampai teks \"Saya muncul saat terlihat\" tampak.","test":"document.getElementById('target').classList.contains('tampak')","hint":"Gulir di dalam kotak bergaris."},"pts":["localStorage untuk data kecil yang bertahan.","IntersectionObserver untuk mendeteksi elemen terlihat.","Bungkus akses storage dengan try/catch."],"q":[["API yang tepat untuk lazy load saat elemen terlihat?",["IntersectionObserver","setInterval yang memeriksa scroll","localStorage"],0,"Lebih hemat daripada memantau scroll terus-menerus."]],"pro":[{"t":"Salin objek bersarang dengan structuredClone","tag":"Trik jarang diketahui","why":"Spread hanya menyalin lapisan teratas, sehingga objek di dalamnya masih dipakai bersama. <code>structuredClone</code> (bawaan browser dan Node 17+) menyalin seluruh isi, termasuk tanggal dan Map.","lang":"js","a":"const asli = { nama: \"Sari\", alamat: { kota: \"Medan\" } };\nconst salinan = { ...asli };\nsalinan.alamat.kota = \"Bandung\";\nconsole.log(asli.alamat.kota);","b":"const asli = { nama: \"Sari\", alamat: { kota: \"Medan\" } };\nconst salinan = structuredClone(asli);\nsalinan.alamat.kota = \"Bandung\";\nconsole.log(asli.alamat.kota);","outA":"Bandung","outB":"Medan"}]},{"lang":"js","b":["<b>Closure</b> terjadi saat fungsi dibuat di dalam fungsi lain dan tetap bisa memakai variabel fungsi luar, bahkan setelah fungsi luar selesai dijalankan. Variabel itu \"terkunci\" bersama fungsinya.","Closure dipakai di mana-mana: event handler yang mengingat id produk, fungsi pabrik seperti <code>buatPenghitung()</code>, sampai hook React. Ia juga cara sederhana membuat data privat, karena variabel di dalamnya tidak bisa diubah dari luar kecuali lewat fungsi yang disediakan.","Jebakan klasik: <code>var</code> di dalam loop berbagi satu variabel untuk semua putaran, sehingga semua callback melihat nilai terakhir. <code>let</code> membuat variabel baru di setiap putaran."],"pts":["Closure: fungsi membawa variabel lingkup luarnya.","Dipakai untuk handler, pabrik fungsi, data privat.","var di loop berbagi satu variabel.","let membuat variabel baru per putaran."],"q":[["Kenapa k.isi bernilai undefined?",["isi adalah variabel di dalam closure, bukan properti objek","Keranjang kosong","Ada error"],0,"Variabel closure bersifat privat."],["Kenapa pakaiVar menghasilkan [3, 3, 3]?",["Semua fungsi berbagi satu variabel i yang akhirnya bernilai 3","Karena map salah","var selalu bernilai 3"],0,"var tidak membuat variabel baru per putaran."]],"code":"function buatKeranjang() {\n  let isi = [];                       // privat, tidak bisa diakses langsung\n  return {\n    tambah(barang) { isi.push(barang); return isi.length; },\n    lihat() { return [...isi]; },\n  };\n}\nconst k = buatKeranjang();\nk.tambah(\"kopi\");\nk.tambah(\"teh\");\nconsole.log(k.lihat(), k.isi);\n\nconst pakaiVar = [], pakaiLet = [];\nfor (var i = 0; i < 3; i++) pakaiVar.push(() => i);\nfor (let j = 0; j < 3; j++) pakaiLet.push(() => j);\nconsole.log(pakaiVar.map((f) => f()), pakaiLet.map((f) => f()));","out":"[ 'kopi', 'teh' ] undefined\n[ 3, 3, 3 ] [ 0, 1, 2 ]"},{},{},{},{},{},{},{"lang":"js","run":false,"b":["Kode modern terdiri dari ratusan modul, JSX, dan TypeScript yang tidak bisa langsung dijalankan browser lama. <b>Bundler</b> menggabungkan dan mengoptimasi semuanya: menghapus kode yang tidak dipakai (tree shaking), memecah file (code splitting), dan mengecilkan ukuran (minify).","<b>Vite</b> kini menjadi pilihan utama: saat pengembangan ia menyajikan modul ES langsung sehingga sangat cepat, dan saat build ia memakai Rollup (atau Rolldown). <b>esbuild</b> dan <b>SWC</b> adalah kompiler super cepat yang ditulis dengan Go dan Rust.","Selain npm, ada <b>pnpm</b> (hemat ruang disk), <b>Yarn</b>, dan <b>Bun</b> (runtime sekaligus package manager yang sangat cepat)."],"code":"// vite.config.js\nimport { defineConfig } from \"vite\";\nimport react from \"@vitejs/plugin-react\";\n\nexport default defineConfig({\n  plugins: [react()],\n  build: {\n    sourcemap: true,\n    rollupOptions: { output: { manualChunks: { react: [\"react\", \"react-dom\"] } } },\n  },\n});\n// $ npm run build\n// dist/assets/react-8f2c.js   142 kB │ gzip: 45 kB\n// dist/assets/index-1b7d.js    18 kB │ gzip:  6 kB","pts":["Bundler: gabung, tree shaking, code splitting, minify.","Vite cepat saat dev, Rollup/Rolldown saat build.","esbuild dan SWC adalah kompiler cepat.","pnpm, Yarn, Bun alternatif npm."],"q":[["Tree shaking berarti?",["Membuang kode yang tidak dipakai","Mengurutkan file","Mengompres gambar"],0,"Hanya kode yang di-import yang ikut."]]},{"lang":"json","run":false,"b":["<b>Formatter</b> seperti Prettier merapikan gaya penulisan otomatis (spasi, tanda kutip, panjang baris), sehingga tim tidak berdebat soal gaya. <b>Linter</b> seperti ESLint mencari pola kode yang berpotensi bug, misalnya variabel tidak dipakai atau dependensi useEffect yang terlewat.","<b>Biome</b> menggabungkan keduanya dalam satu alat yang sangat cepat. Jalankan otomatis saat menyimpan file dan sebelum commit."],"code":"// package.json\n{\n  \"scripts\": {\n    \"lint\": \"eslint .\",\n    \"format\": \"prettier --write .\"\n  }\n}\n// $ npm run lint\n// src/App.jsx\n//   12:9  warning  'total' is assigned a value but never used   no-unused-vars\n//   20:6  warning  React Hook useEffect has a missing dependency: 'id'   react-hooks/exhaustive-deps","pts":["Formatter: gaya seragam otomatis.","Linter: deteksi pola rawan bug.","Biome menggabungkan keduanya."],"q":[["Alat yang mendeteksi variabel tidak terpakai?",["Linter (ESLint)","Formatter (Prettier)","Bundler"],0,"Linter menganalisis makna kode."]]},{},{},{"b":["Framework membantu membangun antarmuka yang rumit dengan komponen dan state. <b>React</b> paling banyak dipakai dan ekosistemnya paling besar. <b>Vue</b> ramah pemula dengan template mirip HTML. <b>Angular</b> lengkap dan kaku, populer di perusahaan besar. <b>Svelte</b> dan <b>SolidJS</b> mengompilasi komponen menjadi kode yang sangat ringan.","Untuk karier di Indonesia, React dan Vue paling banyak diminta lowongan. Konsep intinya sama: komponen, props, state, dan reaktivitas. Kuasai satu dengan baik, framework lain jadi mudah dipelajari."],"code":"// React\nfunction Sapa({ nama }) { return <p>Halo, {nama}</p>; }\n\n<!-- Vue -->\n<template><p>Halo, {{ nama }}</p></template>\n<script setup>defineProps([\"nama\"])</script>\n\n<!-- Svelte -->\n<script>export let nama;</script>\n<p>Halo, {nama}</p>","lang":"jsx","run":false,"pts":["React: ekosistem terbesar.","Vue: ramah pemula.","Angular: lengkap, populer di enterprise.","Svelte/Solid: hasil kompilasi ringan."],"q":[["Konsep yang sama di semua framework modern?",["Komponen dan state","Kelas Java","SQL"],0,"Karena itu pindah framework relatif mudah."]]},{},{},{},{},{},{"lang":"ts","run":false,"b":["Tes end-to-end (E2E) menjalankan browser sungguhan dan meniru pengguna: membuka halaman, mengetik, mengklik, lalu memeriksa hasil. Tes ini paling lambat tapi paling meyakinkan, jadi tulis untuk alur terpenting saja, seperti login dan checkout.","<b>Playwright</b> mendukung Chromium, Firefox, dan WebKit sekaligus, serta menunggu elemen siap secara otomatis. <b>Cypress</b> adalah alternatif populer dengan antarmuka interaktif."],"code":"import { test, expect } from \"@playwright/test\";\n\ntest(\"pembeli bisa menambah produk ke keranjang\", async ({ page }) => {\n  await page.goto(\"https://tokonusantara.id\");\n  await page.getByRole(\"searchbox\", { name: \"Cari produk\" }).fill(\"kopi\");\n  await page.getByRole(\"button\", { name: \"Tambah Kopi Gayo\" }).click();\n  await expect(page.getByText(\"1 barang di keranjang\")).toBeVisible();\n});\n// $ npx playwright test\n//   ✓ pembeli bisa menambah produk ke keranjang (1.2s)","pts":["Piramida tes: banyak unit, sedikit E2E.","Playwright: lintas browser, auto-wait.","Tulis E2E untuk alur paling penting."],"q":[["Tes paling lambat tapi paling mirip pengguna asli?",["End-to-end","Unit","Lint"],0,"E2E menjalankan aplikasi utuh di browser."]]},{"lang":"text","run":false,"b":["Browser menerapkan <b>same-origin policy</b>: JavaScript dari tokonusantara.id tidak boleh membaca respons dari api.lain.com kecuali server itu mengizinkan lewat header <b>CORS</b> (<code>Access-Control-Allow-Origin</code>). Error CORS diperbaiki di server, bukan di frontend.","<b>Content Security Policy</b> membatasi sumber script, gaya, dan gambar. Jika penyerang berhasil menyisipkan <code>&lt;script&gt;</code> lewat komentar, CSP yang ketat mencegahnya berjalan."],"code":"# Browser (dari https://tokonusantara.id) meminta:\nGET https://api.tokonusantara.id/produk\nOrigin: https://tokonusantara.id\n\n# Server mengizinkan:\nAccess-Control-Allow-Origin: https://tokonusantara.id\nContent-Security-Policy: default-src 'self'; script-src 'self'; img-src 'self' https://cdn.tokonusantara.id","pts":["Same-origin policy membatasi baca lintas domain.","CORS diatur di server lewat header.","CSP membatasi sumber script dan konten."],"q":[["Error CORS diperbaiki di mana?",["Server API (header CORS)","Kode React","CSS"],0,"Server yang menentukan origin mana yang boleh."]]},{"b":["<b>OWASP Top 10</b> adalah daftar risiko keamanan web paling umum: kontrol akses yang rusak, kegagalan kriptografi, injeksi (SQL injection, XSS), desain tidak aman, konfigurasi salah, komponen usang, autentikasi lemah, dan lainnya.","Di frontend, risiko paling sering adalah <b>XSS</b> (cross-site scripting): input pengguna ditampilkan sebagai HTML sehingga script penyerang ikut berjalan. Lawannya: tampilkan input dengan <code>textContent</code>, bukan <code>innerHTML</code>, dan sanitasi HTML jika benar-benar perlu."],"html":"<label>Komentar: <input id=\"k\" value=\"&lt;img src=x onerror=&quot;document.body.style.background='#B23A2E'&quot;&gt;\"></label>\n<button id=\"a\">Tampilkan (innerHTML)</button> <button id=\"b\">Tampilkan (textContent)</button>\n<div id=\"out\" style=\"margin-top:8px;padding:8px;border:1px solid #ddd\"></div>","js":"const out = document.getElementById(\"out\"), k = document.getElementById(\"k\");\ndocument.getElementById(\"a\").onclick = () => { out.innerHTML = k.value; };      // berbahaya\ndocument.getElementById(\"b\").onclick = () => { out.textContent = k.value; };    // aman","pts":["Kenali OWASP Top 10.","XSS terjadi saat input pengguna dirender sebagai HTML.","Pakai textContent; sanitasi bila harus menampilkan HTML.","React otomatis meng-escape teks di JSX."],"q":[["Cara aman menampilkan komentar pengguna?",["textContent","innerHTML","eval"],0,"Teks tidak diurai sebagai HTML."]]},{"lang":"text","run":false,"b":["<b>Session cookie</b>: server menyimpan sesi dan browser menyimpan id-nya di cookie <code>HttpOnly; Secure; SameSite</code> yang tidak bisa dibaca JavaScript. Cara paling aman untuk aplikasi web biasa.","<b>Token (JWT)</b>: server memberi token bertanda tangan yang dikirim di header Authorization. Cocok untuk API dan aplikasi mobile, tapi jangan simpan di localStorage jika situs rentan XSS. <b>OAuth / OpenID Connect</b> untuk \"Masuk dengan Google\". <b>Passkey</b> menggantikan kata sandi dengan kunci di perangkat."],"code":"# Login berhasil, server mengirim cookie sesi:\nSet-Cookie: sid=8f2c1e...; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=86400\n\n# Permintaan berikutnya otomatis membawa cookie:\nGET /akun\nCookie: sid=8f2c1e...\n\n# Alternatif token untuk API:\nGET /api/pesanan\nAuthorization: Bearer eyJhbGciOiJIUzI1NiJ9...","pts":["Cookie HttpOnly + Secure + SameSite untuk sesi web.","JWT untuk API/mobile; hati-hati tempat penyimpanannya.","OAuth/OIDC untuk login pihak ketiga.","Passkey: tanpa kata sandi."],"q":[["Flag cookie yang mencegah JavaScript membacanya?",["HttpOnly","Secure","Path"],0,"Melindungi sesi dari XSS."]]},{"viz":"vitals","b":["Google mengukur pengalaman pengguna dengan <b>Core Web Vitals</b>: <b>LCP</b> (Largest Contentful Paint, kapan konten utama tampil, target di bawah 2,5 detik), <b>INP</b> (Interaction to Next Paint, seberapa cepat halaman merespons klik, di bawah 200 ms), dan <b>CLS</b> (Cumulative Layout Shift, seberapa banyak tata letak melompat, di bawah 0,1).","<b>Lighthouse</b> di Chrome DevTools mengaudit performa, aksesibilitas, SEO, dan praktik terbaik, lalu memberi saran konkret. Tab Network dan Performance di DevTools menunjukkan file mana yang lambat.","Cara cepat memperbaiki: kompres gambar (WebP/AVIF) dan beri ukuran, lazy load gambar di bawah, kurangi JavaScript, pakai code splitting, dan muat font dengan <code>font-display: swap</code>."],"pts":["LCP < 2,5 s, INP < 200 ms, CLS < 0,1.","Lighthouse memberi skor dan saran.","Gambar dan JavaScript adalah penyebab paling umum situs lambat."],"q":[["Gambar tanpa width/height paling memengaruhi metrik?",["CLS","LCP","INP"],0,"Tata letak melompat saat gambar selesai dimuat."]]},{},{"lang":"js","b":["Event seperti <code>input</code>, <code>scroll</code>, dan <code>resize</code> bisa terpicu puluhan kali per detik. Kalau setiap event memanggil API pencarian, server kebanjiran dan hasilnya datang tidak berurutan.","<b>Debounce</b> menunggu sampai event berhenti selama jeda tertentu, lalu menjalankan fungsi sekali. Cocok untuk kotak pencarian: kirim permintaan 300 ms setelah pengguna berhenti mengetik. <b>Throttle</b> menjalankan fungsi paling banyak sekali per selang waktu, cocok untuk scroll atau menyimpan posisi.","Contoh di bawah mensimulasikan 5 ketukan cepat lalu jeda. Debounce hanya mencari sekali dengan kata terakhir."],"pts":["Debounce: jalankan sekali setelah event berhenti.","Throttle: paling banyak sekali per selang waktu.","Pencarian: debounce ±300 ms.","Scroll/resize: throttle atau requestAnimationFrame."],"q":[["Teknik untuk kotak pencarian yang memanggil API?",["Debounce","Throttle 0 ms","Panggil setiap ketukan"],0,"Permintaan dikirim setelah pengguna berhenti mengetik."],["Kenapa clearTimeout dipanggil di setiap event?",["Membatalkan jadwal sebelumnya agar hanya event terakhir yang dijalankan","Mempercepat timer","Menghapus event listener"],0,"Itulah inti debounce."]],"code":"function debounce(fn, ms) {\n  let t;\n  return (...args) => {\n    clearTimeout(t);\n    t = setTimeout(() => fn(...args), ms);\n  };\n}\n\nconst panggilan = [];\nconst cari = debounce((kata) => {\n  panggilan.push(kata);\n  console.log(\"cari ke server:\", kata);\n}, 300);\n\n[\"k\", \"ko\", \"kop\", \"kopi\", \"kopi g\"].forEach((kata, i) => setTimeout(() => cari(kata), i * 50));\nsetTimeout(() => console.log(\"jumlah panggilan:\", panggilan.length), 700);","out":"cari ke server: kopi g\njumlah panggilan: 1"},{"b":["<b>Web Components</b> adalah komponen bawaan browser tanpa framework. <b>Custom element</b> mendefinisikan tag sendiri seperti <code>&lt;kartu-produk&gt;</code>. <b>Shadow DOM</b> membungkus HTML dan CSS-nya sehingga tidak bocor ke luar dan tidak terganggu gaya luar. <b>&lt;template&gt;</b> menyimpan potongan HTML yang belum dirender.","Web Components bisa dipakai di React, Vue, atau HTML biasa, cocok untuk design system lintas framework."],"html":"<kartu-produk nama=\"Kopi Gayo\" harga=\"85000\"></kartu-produk>\n<kartu-produk nama=\"Teh Melati\" harga=\"25000\"></kartu-produk>\n<p class=\"kartu\">Paragraf luar dengan class kartu tidak terpengaruh gaya di dalam komponen.</p>","js":"class KartuProduk extends HTMLElement {\n  connectedCallback() {\n    const root = this.attachShadow({ mode: \"open\" });\n    const harga = Number(this.getAttribute(\"harga\")).toLocaleString(\"id-ID\");\n    root.innerHTML = `\n      <style>.kartu{border:1px solid #2E5E8C;border-radius:10px;padding:8px 12px;margin:6px 0;font:14px sans-serif}\n             b{color:#2E5E8C}</style>\n      <div class=\"kartu\"><b>${this.getAttribute(\"nama\")}</b> · Rp${harga}</div>`;\n  }\n}\ncustomElements.define(\"kartu-produk\", KartuProduk);","task":{"q":"Tambahkan satu &lt;kartu-produk&gt; lagi untuk \"Madu Hutan\" seharga 120000.","test":"[...document.querySelectorAll('kartu-produk')].some(e=>/Madu/.test(e.getAttribute('nama')||''))","hint":"<kartu-produk nama=\"Madu Hutan\" harga=\"120000\"></kartu-produk>"},"pts":["customElements.define membuat tag baru (wajib ada tanda hubung).","Shadow DOM mengisolasi HTML dan CSS.","Bisa dipakai di framework mana pun."],"q":[["Syarat nama custom element?",["Mengandung tanda hubung","Diawali huruf kapital","Maksimal 5 huruf"],0,"Contoh: kartu-produk."]]},{"lang":"js","run":false,"b":["<b>Progressive Web App</b> adalah situs yang bisa dipasang di layar utama, bekerja offline, dan mengirim notifikasi. Syaratnya: HTTPS, file <code>manifest.webmanifest</code> (nama, ikon, warna), dan <b>service worker</b>.","Service worker adalah script yang berjalan di latar belakang dan bisa mencegat permintaan jaringan. Dengan itu, halaman dan aset bisa diambil dari cache saat sinyal hilang, hal yang penting di daerah dengan koneksi tidak stabil."],"code":"// sw.js — cache dulu, jaringan kemudian\nconst CACHE = \"toko-v1\";\nself.addEventListener(\"install\", e => {\n  e.waitUntil(caches.open(CACHE).then(c => c.addAll([\"/\", \"/app.js\", \"/gaya.css\", \"/offline.html\"])));\n});\nself.addEventListener(\"fetch\", e => {\n  e.respondWith(\n    caches.match(e.request).then(hit => hit || fetch(e.request).catch(() => caches.match(\"/offline.html\")))\n  );\n});\n\n// main.js\nif (\"serviceWorker\" in navigator) navigator.serviceWorker.register(\"/sw.js\");","pts":["PWA: HTTPS + manifest + service worker.","Service worker mencegat request dan memakai cache.","Penting untuk pengguna dengan koneksi tidak stabil."],"q":[["Komponen PWA yang memungkinkan offline?",["Service worker","Manifest","Favicon"],0,"Ia menyajikan dari cache saat offline."]]},{"viz":"ssr","b":["<b>CSR</b> (client-side rendering): server mengirim HTML hampir kosong, JavaScript membangun halaman di browser. Interaktif setelah JS dimuat, tapi tampilan pertama lebih lambat dan kurang ramah SEO.","<b>SSR</b> (server-side rendering): HTML dibuat di server untuk setiap permintaan, lalu JavaScript \"menghidupkannya\" (hydration). <b>SSG</b> (static site generation): HTML dibuat sekali saat build, sangat cepat dan murah.","Framework meta seperti <b>Next.js</b> (React), <b>Nuxt</b> (Vue), <b>SvelteKit</b>, dan <b>Astro</b> bisa mencampur ketiganya per halaman. Situs dokumentasi atau blog cocok dengan SSG; dashboard pribadi cocok dengan CSR; toko online cocok dengan SSR/SSG campuran."],"pts":["CSR: dirender di browser.","SSR: dirender di server per permintaan.","SSG: dirender saat build.","Framework meta mencampur per halaman."],"q":[["Blog yang jarang berubah paling cocok dengan?",["SSG","CSR","SSR per permintaan"],0,"HTML sudah jadi sejak build."]]},{"lang":"text","run":false,"b":["Di REST, setiap sumber data punya alamat sendiri (<code>/produk</code>, <code>/produk/1/ulasan</code>). Di <b>GraphQL</b>, ada satu endpoint dan klien menulis <b>query</b> yang menyebut persis kolom yang dibutuhkan. Tidak ada data berlebih, dan data bertingkat diambil sekali jalan.","Klien seperti Apollo dan Relay mengelola cache hasil query di frontend."],"code":"# query dari klien\nquery {\n  produk(id: 1) {\n    nama\n    harga\n    ulasan(terbaru: 2) { bintang komentar }\n  }\n}\n\n# respons server: bentuknya sama dengan query\n{ \"data\": { \"produk\": { \"nama\": \"Kopi Gayo\", \"harga\": 85000,\n  \"ulasan\": [ { \"bintang\": 5, \"komentar\": \"Wangi!\" }, { \"bintang\": 4, \"komentar\": \"Mantap\" } ] } } }","pts":["Satu endpoint, klien menentukan bentuk data.","Tidak ada over-fetching.","Apollo/Relay mengelola cache."],"q":[["Keunggulan utama GraphQL?",["Klien meminta tepat kolom yang dibutuhkan","Tidak butuh server","Lebih aman otomatis"],0,"Bentuk respons mengikuti query."]]},{},{"b":["<b>Large Language Model</b> (LLM) dilatih memprediksi kata berikutnya dari teks dalam jumlah sangat besar. Hasilnya model yang bisa menjelaskan, menulis, dan memperbaiki kode, tetapi juga bisa keliru dengan percaya diri. Karena itu, hasilnya selalu perlu kamu baca dan uji.","Asisten coding seperti <b>Claude Code</b>, <b>GitHub Copilot</b>, dan <b>Cursor</b> membantu menulis kode, refactor, membuat tes dan dokumentasi, serta meninjau pull request. <b>Agen</b> AI bisa menjalankan perintah dan mengubah banyak file; <b>MCP</b> (Model Context Protocol) menghubungkan AI dengan alat dan data lain.","Prompt yang baik memberi konteks (proyek, teknologi), tugas yang jelas, batasan (gaya kode, pustaka yang boleh), dan contoh hasil yang diinginkan."],"code":"Konteks: proyek React + TypeScript + Tailwind, komponen di src/components.\nTugas: buat komponen KartuProduk yang menampilkan nama, harga (format Rupiah),\ndan tombol \"Tambah ke keranjang\".\nBatasan: tanpa pustaka tambahan, aksesibel (button asli, alt pada gambar),\ntulis juga satu tes Vitest + Testing Library.\nContoh pemakaian: <KartuProduk nama=\"Kopi Gayo\" harga={85000} onTambah={...} />","lang":"text","run":false,"pts":["LLM memprediksi teks; bisa salah dengan yakin.","Selalu baca, jalankan, dan uji kode hasil AI.","Prompt: konteks, tugas, batasan, contoh.","Agen dan MCP memperluas kemampuan AI."],"q":[["Sikap yang benar terhadap kode buatan AI?",["Baca dan uji seperti kode dari rekan kerja","Langsung deploy","Tidak boleh dipakai sama sekali"],0,"Kamu tetap bertanggung jawab atas kodenya."]]},{"lang":"js","run":false,"b":["Fitur AI di aplikasi (chatbot, ringkasan, pencarian semantik) memanggil API model dari penyedia seperti Anthropic, OpenAI, atau Google. <b>Kunci API tidak boleh ada di kode frontend</b>; panggil lewat server atau fungsi serverless milikmu.","Jawaban model dikirim bertahap (<b>streaming</b>) agar pengguna langsung melihat teks muncul, bukan menunggu jawaban utuh. Di frontend, baca stream dengan <code>response.body.getReader()</code>."],"code":"// Frontend: membaca jawaban yang di-stream dari server kita sendiri\nasync function tanya(pertanyaan, tulis) {\n  const res = await fetch(\"/api/tanya\", { method: \"POST\", body: JSON.stringify({ pertanyaan }) });\n  const reader = res.body.getReader();\n  const dec = new TextDecoder();\n  while (true) {\n    const { value, done } = await reader.read();\n    if (done) break;\n    tulis(dec.decode(value, { stream: true }));   // tampilkan potongan teks segera\n  }\n}\n// Server (/api/tanya) yang memegang kunci API dan meneruskan stream dari penyedia model.","pts":["Kunci API selalu di server.","Streaming membuat jawaban terasa cepat.","Tampilkan status, tangani error, dan beri tahu bahwa jawaban bisa keliru."],"q":[["Di mana kunci API model AI disimpan?",["Di server/fungsi serverless","Di kode React","Di localStorage"],0,"Kode frontend bisa dibaca siapa pun."]]},{"stack":"React + Vite + TypeScript","brief":"Bangun aplikasi yang menampilkan cuaca dan kualitas udara beberapa kota Indonesia dari API publik, lengkap dengan pencarian, favorit, mode gelap, dan dukungan offline sederhana.","feats":["Proyek Vite + React + TypeScript dengan ESLint dan Prettier","Pencarian kota dengan debounce dan keadaan loading/error","Data diambil dengan TanStack Query (cache dan retry)","Kota favorit tersimpan di localStorage","Mode gelap dengan variabel CSS dan prefers-color-scheme","Skor Lighthouse performa dan aksesibilitas minimal 90","Minimal 3 unit test (Vitest) dan 1 tes E2E (Playwright)","Kunci API (jika ada) tidak bocor ke kode frontend","Terbit di Vercel/Netlify dengan deploy otomatis dari GitHub"],"steps":["Rancang tampilan di kertas atau Figma.","Bangun komponen dengan data tiruan.","Sambungkan API dan tangani semua keadaan.","Ukur dengan Lighthouse, tulis tes, lalu terbitkan."],"files":[["src/hooks/useCuaca.ts","ts","import { useQuery } from \"@tanstack/react-query\";\n\nexport type Cuaca = { kota: string; suhu: number; kondisi: string };\n\nexport function useCuaca(lat: number, lon: number) {\n  return useQuery({\n    queryKey: [\"cuaca\", lat, lon],\n    queryFn: async (): Promise<Cuaca> => {\n      const url = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,weather_code`;\n      const res = await fetch(url);\n      if (!res.ok) throw new Error(\"Gagal memuat cuaca\");\n      const j = await res.json();\n      return { kota: `${lat},${lon}`, suhu: j.current.temperature_2m, kondisi: String(j.current.weather_code) };\n    },\n    staleTime: 10 * 60 * 1000,\n  });\n}"]]}]);
